def count_vowels(s):
    # Create a map of char-node
    map = dict()
    # Add root node
    root = Node('')

    # Add each character and its count to map
    for char in s:
        node = root
        for ch in char.lower():
            if ch not in map:
                new_node = Node(ch)
                node.head = new_node
                map[ch] = new_node
            else:
