def count_vowels(in_str):

    # Convert input to lower case
    in_str = in_str.lower()

    # Helper function to count vowels recursively
    def count_vowels_recursive(cur_index, vowels_count):
        if cur_index >= len(in_str):
            # Base case: no more characters to check
            return vowels_count

        # Recursive case: check the next character
        if in_str[cur_index] in 'aeiou':
            # Increment vowels count if the character is a vowel
            return count_vowels_recursive(cur_index + 1, vowels_count + 1)
        else:
            return count_vowels_recursive(cur_index + 1, vowels_count)

    # Start the recursion from the first character
    return count_vowels_recursive(0, 0)


