def count_vowels(s: str) -> dict:
    # Initialize a dictionary to store vowel counts
    vowel_counts = {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}

    # Convert the string to lowercase to make the function case-insensitive
    s = s.lower()

    # Iterate over each character in the string
    for char in s:
        # If the character is a vowel (case-insensitive), increment the count for that vowel
        if char in ('a', 'e', 'i', 'o', 'u'):
            if char in vowel_counts:
                vowel_counts[char] += 1

    # Sort the dictionary in descending order based on the counts
    sorted_vowels = sorted(vowel_counts.items(), key=lambda x: x[1], reverse=True)

    return dict(sorted_vowels)

