def count_vowels(s, count=0):
    vowels = 'aeiou'
    # Base case: if the string is empty, return the count
    if not s:
        return count

    # Recursive case: if the corresponding character is a vowel,
    # increment the count and continue with the remaining string
    if s[0] in vowels:
        return count_vowels(s[1:], count + 1)
    # If the corresponding character is not a vowel, continue with the
    # remaining string without incrementing the count
    else:
        return count_vowels(s[1:], count)

